#pragma once

// Runs a kernel on the CPU as the GPU does: dispatch(kernel, gx, gy, gz) runs every workgroup of the
// grid (Kernel::workgroup, generated by tools/wgsl2cpp.py). Workgroups are independent, so native
// builds spread them over the hardware threads, each thread with its own copy of the kernel (its
// workgroup and per-lane memory); WebAssembly runs them in order.
//
// Native builds keep one pool of worker threads for the whole run, with no locks: a dispatch
// publishes its job and bumps an epoch the workers spin on, each thread claims chunks of workgroups
// with a compare-exchange, and the caller works too, then spins until every worker has checked out.
// Idle workers spin briefly, then yield; nothing locks or blocks.

#include <algorithm>
#include <atomic>
#include <cstdint>
#include <memory>
#include <vector>
#ifndef __EMSCRIPTEN__
#include <thread>
#if defined(__x86_64__) || defined(__i386__)
#include <immintrin.h>
#endif
#endif

namespace ofm::detail {

#ifndef __EMSCRIPTEN__
inline void relax() {
#if defined(__x86_64__) || defined(__i386__)
  _mm_pause();
#else
  std::this_thread::yield();
#endif
}

class Pool {
 public:
  static Pool& get() {
    static Pool p;
    return p;
  }
  std::uint32_t threads() const { return std::uint32_t(workers_.size()) + 1; }
  /// Runs body(thread) on `use` threads (the caller is thread 0) and returns when all are done.
  template <class F>
  void run(std::uint32_t use, F& body) {
    use = std::min(use, threads());
    if (use <= 1) {
      body(0u);
      return;
    }
    job_ = &body;
    call_ = [](void* b, std::uint32_t t) { (*static_cast<F*>(b))(t); };
    use_.store(use, std::memory_order_relaxed);
    pending_.store(use - 1, std::memory_order_relaxed);
    epoch_.fetch_add(1, std::memory_order_release);
    body(0u);
    while (pending_.load(std::memory_order_acquire) != 0) relax();
  }
  ~Pool() {
    stop_.store(true, std::memory_order_release);
    epoch_.fetch_add(1, std::memory_order_release);
    for (auto& t : workers_) t.join();
  }

 private:
  Pool() {
    const std::uint32_t n = std::max(1u, std::thread::hardware_concurrency());
    for (std::uint32_t t = 1; t < n; ++t) workers_.emplace_back([this, t] { loop(t); });
  }
  void loop(std::uint32_t t) {
    std::uint64_t seen = 0;
    for (;;) {
      std::uint64_t e;
      for (std::uint32_t spin = 0; (e = epoch_.load(std::memory_order_acquire)) == seen; ++spin)
        if (spin < 4096) relax(); else std::this_thread::yield();
      seen = e;
      if (stop_.load(std::memory_order_acquire)) return;
      if (t < use_.load(std::memory_order_relaxed)) {
        call_(job_, t);
        pending_.fetch_sub(1, std::memory_order_acq_rel);
      }
    }
  }
  std::vector<std::thread> workers_;
  std::atomic<std::uint64_t> epoch_{0};
  std::atomic<std::uint32_t> use_{0}, pending_{0};
  std::atomic<bool> stop_{false};
  void* job_ = nullptr;
  void (*call_)(void*, std::uint32_t) = nullptr;
};
#endif

template <class Kernel>
void dispatch(const Kernel& kernel, std::uint32_t gx, std::uint32_t gy = 1, std::uint32_t gz = 1) {
  const std::uint32_t n = gx * gy * gz;
  if (n == 0) return;
#ifndef __EMSCRIPTEN__
  // Each thread claims a chunk of workgroups with a compare-exchange (about 8 chunks a thread, so the
  // atomic is touched rarely and the tail still balances), then runs them on its own copy.
  std::atomic<std::uint32_t> next{0};
  const std::uint32_t chunk = std::max<std::uint32_t>(1, n / (8 * Pool::get().threads()));
  auto body = [&](std::uint32_t) {
    auto k = std::make_unique<Kernel>(kernel);
    for (std::uint32_t w = next.load(std::memory_order_relaxed);;) {
      if (w >= n) break;
      const std::uint32_t end = std::min(n, w + chunk);
      if (!next.compare_exchange_weak(w, end, std::memory_order_relaxed)) continue;  // w now holds the current value
      for (; w < end; ++w) k->workgroup({w % gx, (w / gx) % gy, w / (gx * gy)});
      w = next.load(std::memory_order_relaxed);
    }
  };
  Pool::get().run(n, body);
#else
  auto k = std::make_unique<Kernel>(kernel);
  for (std::uint32_t w = 0; w < n; ++w) k->workgroup({w % gx, (w / gx) % gy, w / (gx * gy)});
#endif
}

inline std::uint32_t groups(std::uint32_t n, std::uint32_t size) { return (n + size - 1) / size; }

}  // namespace ofm::detail
